import sys
from docx import Document

path = sys.argv[1]
doc = Document(path)

repls = [
("Results: The final cohort included",
"Results: The final cohort included 60,476 patients, of whom 38,370 (63.4%) had delayed entry into TB-designated care. LightGBM showed the highest point estimate of discrimination in the held-out test set (ROC-AUC 0.699; PR-AUC 0.793), and XGBoost performed almost identically (ROC-AUC 0.698). At the training-set Youden-index threshold, LightGBM achieved an accuracy of 0.649, sensitivity of 0.675, and specificity of 0.605. Geographic accessibility accounted for 15.6% of total mean absolute SHAP contribution and ranked third among nine predictor domains, after temporal features (28.1%) and demographics (21.5%). Removing the geographic domain did not materially change discrimination (\u0394ROC-AUC 0.003, 95% CI \u22120.001 to 0.006); adding the six geographic variables to a conventional demographic and clinical model improved discrimination (\u0394ROC-AUC 0.018, 95% CI 0.013\u20130.022). Seven-day threshold and subgroup analyses showed consistent model behaviour. Temporal validation yielded a lower ROC-AUC (0.568), indicating limited transportability to later years."),
("Conclusions: Delayed entry into TB-designated care was common",
"Conclusions: Delayed entry into TB-designated care was common in this mountainous, multi-ethnic region. Geographic accessibility was one of several informative predictor domains, alongside temporal, demographic, and key-population characteristics. Removing the geographic domain did not materially change discrimination, whereas adding it to a conventional demographic and clinical model improved discrimination (\u0394ROC-AUC 0.018), indicating incremental value relative to conventional predictors. The model showed moderate discrimination and is best suited to retrospective risk characterisation and service planning. Linking routine TB surveillance with spatial accessibility measures may support targeted outreach, referral coordination, and service planning; prospective and external validation, including spatial validation, is needed before operational use, and temporal validation showed limited transportability (ROC-AUC 0.568)."),
("Tuberculosis (TB) remains one of the most important",
"Tuberculosis (TB) remains one of the most important infectious disease challenges globally[1\u20133]. Although treatment is effective and TB control programmes have achieved substantial gains in many settings, delayed entry into diagnosis and treatment pathways continues to undermine early case detection, timely treatment, and transmission control. The period between symptom onset and entry into effective TB care is especially important because infectious pulmonary TB patients may continue to transmit disease before diagnosis and treatment initiation. Patient delay is therefore both a clinical problem and a population-level public-health concern[4\u20136]."),
("The calibration plot showed acceptable overall agreement",
"The calibration plot showed acceptable overall agreement between predicted and observed delay probabilities, with some overprediction in the lower-to-middle range and closer agreement at higher probabilities (Figure 3). At low thresholds, net benefit was essentially identical to treat-all (0.594 vs 0.594 at 0.10; 0.544 vs 0.543 at 0.20). At higher thresholds, including 0.625, the model exceeded treat-all (0.187 vs 0.025), but the no-geography model performed similarly (0.187), so this benefit was not specific to geographic accessibility (Table 3). The model is therefore suited to risk stratification in planning, not individual decision-making."),
("Model interpretation showed that several individual",
"Model interpretation showed that several individual geographic variables, including road-network distance and travel time, were prominent at the variable level. Because the geographic variables were correlated, individual rankings reflect a shared spatial-access construct rather than independent contributions. Occupation, symptom month, symptom year, nonlinear age terms, referral status, and symptom-related variables also contributed to prediction. At the domain level, geographic accessibility accounted for 15.6% of total mean absolute SHAP contribution and ranked third among nine domains, after temporal features (28.1%) and demographics (21.5%); key-population indicators ranked fourth (10.8%). Because domain sums depend on the number of features per domain (30 key-population features versus six geographic features), grouped permutation importance is reported in the Supplement. Figure 4 shows the direction and magnitude of feature effects. Geographic accessibility was an important domain, but not the largest contributor."),
("Domain-level SHAP decomposition of the final raw-variable model showed",
"Domain-level SHAP decomposition of the final raw-variable model showed that geographic accessibility accounted for 15.6% of total mean absolute SHAP contribution, ranking third among nine predictor domains, after temporal features (28.1%) and demographics (21.5%). Partial dependence plots for the geographic terms are shown in Supplementary Figure S9; they describe model behaviour, not causal effects."),
("In a prespecified incremental analysis, we refitted",
"In a prespecified incremental analysis, we refitted the final LightGBM model on the same training split after removing the six geographic variables. Discrimination was essentially unchanged (ROC-AUC 0.696 vs 0.699; \u0394ROC-AUC 0.003, 95% CI \u22120.001 to 0.006; DeLong P = 0.09), as were PR-AUC (0.790 vs 0.793; \u0394 0.002, 95% CI \u22120.001 to 0.005), the Brier score (0.204 vs 0.204; \u0394 \u22120.0003, 95% CI \u22120.0011 to 0.0004), and calibration intercept and slope (Supplementary Table S15). Net benefit was similar across thresholds, and the no-geography model performed marginally better at some thresholds; the benefit of the full model at 0.625 (0.187 vs 0.025 for treat-all) was therefore not specific to geographic accessibility (0.187 without geography). In a secondary comparison, adding the six geographic variables to a conventional demographic and clinical model improved ROC-AUC from 0.639 to 0.657 (\u0394 0.018, 95% CI 0.013\u20130.022; DeLong P < 0.001), PR-AUC from 0.731 to 0.748, and the Brier score from 0.219 to 0.216 (Supplementary Table S28). A placebo model with the six geographic variables randomly permuted achieved ROC-AUC 0.634\u20130.635, indicating that the gain reflected geographic information rather than additional model capacity. Geographic accessibility therefore adds information beyond conventional predictors, although much of this information overlaps with the broader predictor set in the full model."),
("Grouped permutation importance on the held-out test set showed",
"Grouped permutation importance on the held-out test set showed that permuting the geographic domain reduced ROC-AUC by 0.016 (95% CI 0.013\u20130.019), the fourth-largest drop, similar to key-population indicators (0.017; 95% CI 0.015\u20130.019) and after temporal features (0.113) and demographics (0.035). Geographic accessibility therefore contributes to prediction, but other domains compensate when it is removed, and it does not materially improve overall discrimination (Supplementary Table S16)."),
("This study adds to the tuberculosis (TB) patient-delay literature",
"In this mountainous, multi-ethnic setting, delayed entry into TB-designated care was common and was predicted by several domains. Geographic accessibility was one of the more informative domains, but it ranked third in domain-level SHAP contribution, after temporal features and demographics[15,16]. These accessibility patterns may change with road construction, population redistribution, and the relocation of diagnostic capacity, but our cross-sectional data cannot quantify such change[17,18]. The final model had moderate discrimination, consistent with the complexity of care-seeking behaviour. The results show that delay is distributed across temporal, demographic, key-population, and spatial dimensions. Patient source, occupation, insurance status, and symptom profile have dominated previous discussions; our results indicate that physical accessibility of the designated TB network is relevant but not predominant in this setting."),
("The result should therefore be read less as an algorithmic comparison",
"These results extend previous work on TB care pathways. Earlier studies have shown that delay is influenced by provider choice, distance, insurance, stigma, migration, occupation, symptoms, and health-system organisation[11\u201313]. Patient source, insurance type, ethnicity, and occupation remained predictive in our model. Geographic accessibility and these conventional determinants carry overlapping predictive information, and the incremental analysis showed that geography does not improve discrimination beyond the other domains. Formal mediation analysis would be needed to test whether conventional associations are attenuated by access measures."),
("The contribution of geographic accessibility is plausible",
"Geographic accessibility showed a substantial domain-level SHAP share (15.6%), but removing the domain did not materially change discrimination, indicating overlap with other predictors. Adding the six geographic variables to a conventional demographic and clinical model improved discrimination (\u0394ROC-AUC 0.018), so geography is informative relative to conventional predictors even though it is not independently decisive in the full model. In Guangxi and Guizhou, mountainous terrain, dispersed settlements, and uneven diagnostic capacity can make the route into TB-designated care different from the route into general health care. A patient may live near a village clinic, township hospital, or pharmacy and still face delay before reaching an institution able to confirm TB, initiate the formal pathway, or complete notification. This distinction matters because the outcome was delayed entry into TB-designated care, not delay before any health contact[11]."),
("This does not mean that distance alone",
"Distance alone is unlikely to be a causal determinant. The distance variables summarise related burdens: road quality, terrain, time away from work, transport cost, availability of transport, and the spatial distribution of designated facilities. Because the variables were measured at village or community centroids, they also capture unmeasured local context. The strong correlations among distance and travel-time measures reflect a single spatial-access construct, not separate causal effects. For public-health planning, the construct is what matters: patients in areas poorly connected to TB-designated services may need a different model of case finding and referral support."),
("Patient source as a pathway marker rather than an isolated determinant",
"Patient source as a pathway marker"),
("In our analysis, patient-source variables remained predictive",
"In our analysis, patient-source variables remained predictive but were slightly less prominent than geographic accessibility at the domain level (8.2% versus 15.6% of total mean absolute SHAP contribution). Patient source is therefore best read as a pathway marker embedded within geography. Active screening can partly bypass the need for patients to travel to a designated facility, whereas direct presentation and referral depend on the patient's ability to move through a spatially distributed care system. The lower domain-level contribution of patient source after including detailed access measures does not make case-finding pathway unimportant; some of what previous studies attributed to patient source may reflect unmeasured access to the designated TB network."),
("This interpretation is more useful for programme design",
"This interpretation is useful for programme design and is a hypothesis, not a causal finding. It suggests two complementary interventions. First, outreach and mobile screening should be prioritised for communities with poor road-network access to designated facilities. Second, referral links from non-designated providers, township-level institutions, and general hospitals to TB-designated facilities should be strengthened. In practice, patient-source categories identify the route into care, while geographic variables identify the difficulty of travelling that route."),
("The relatively modest contribution of insurance type",
"The modest contribution of insurance type suggests that financial protection alone does not explain delay in this setting. Insurance may reduce medical payment barriers, but it does not remove transport costs, lost work time, or the practical burden of reaching a TB-designated institution. In mountainous areas, the decisive barrier may be the combined cost of travel, time, and administrative navigation, not nominal insurance status. TB delay interventions therefore need to address more than insurance coverage or reimbursement. Transport-aware service planning and referral support are likely to be equally important."),
("This point is consistent with earlier TB delay research",
"This point is consistent with earlier TB delay research in which ethnic minority status, migrant status, and remote settings were associated with longer delays. Our results suggest that part of these associations may be spatially structured. Once road-network and distance measures are represented directly, ethnicity-related signals are better read as residual social and service-access context, not independent biological or cultural explanations. Where such signals persist, they may point to language barriers, trust in formal services, differences in symptom interpretation, preferences for local or traditional providers, or reduced familiarity with the designated-care pathway."),
("Temporal variables accounted for the largest domain-level SHAP contribution",
"Temporal variables accounted for the largest domain-level SHAP contribution (28.1%), including symptom month and year. This may partly reflect documentation practices: symptom text was missing for 85.5% of patients, 85.8% were coded as asymptomatic, and the recorded symptom-onset date coincided with the first-visit date in 7.6% of patients. Symptom variables therefore may not capture true symptom burden. The temporal signal needs cautious interpretation; it does not imply that symptoms are unimportant in care-seeking."),
("This distinction matters for intervention design",
"This distinction matters for intervention design. If symptom season contributes to delay, TB programmes could plan outreach around agricultural and climatic cycles instead of relying only on fixed annual schedules. Mobile screening, sputum transport, public communication, and referral follow-up could be intensified before periods when travel barriers or opportunity costs are expected to rise. The seasonal signal is therefore directly relevant to planning."),
("This study has several strengths",
"This study has several strengths. It used a large routine surveillance cohort from two provinces where TB control is complicated by mountainous terrain, ethnic diversity, and variable access to services. It focused on delayed entry into TB-designated care, an operational outcome directly relevant to programme performance. It incorporated fine-scale geographic accessibility measures rather than relying only on rural residence or administrative area, and it assessed both variable-level and domain-level importance. It also evaluated calibration, decision curve analysis, threshold sensitivity, subgroup performance, and correlation structure. Finally, we distinguish predictive contribution from causal effect and state the limits of the retrospective design."),
("Several limitations should be considered",
"This study has several limitations. First, the outcome captures the first recorded visit to a TB-designated facility, not the first contact with any healthcare provider; visits to pharmacies, private clinics, non-designated facilities, or traditional providers are not recorded, so the outcome includes provider and referral time and is not a pure patient delay. Second, in 7.6% of patients the recorded symptom-onset date coincided with the first-visit date, and symptom text was missing for 85.5%; symptom onset may therefore be imprecisely measured, and 85.8% of patients were coded asymptomatic despite an onset-based outcome. Third, most predictors, including patient source and symptom severity, are recorded at registration after the delay has occurred; the model is therefore a retrospective risk-characterisation tool, not an early-warning system. Fourth, important behavioural and socioeconomic variables were unavailable, including income, education, health literacy, stigma, household support, transport cost, and perceived severity; poverty status was missing for 80.9% of patients and was not modelled. Fifth, insurance values were imputed from residence and occupation for 90.1% of patients (100% in Guangxi and 46.6% in Guizhou), and key-population Unknown categories increased sharply after 2022 and were universal in Guizhou during 2022\u20132024, consistent with data-system changes (Supplementary Tables S23\u2013S24); these domains are not individual risk factors. Sixth, the model achieved moderate discrimination (ROC-AUC 0.699) and showed no net benefit over treat-all at low decision thresholds, indicating that routine surveillance and accessibility data explain only part of the delay process. Seventh, the primary validation used a random held-out split, which can allow location memorisation because patients from the same village share identical geographic values; temporal validation showed limited transportability (ROC-AUC 0.568, calibration slope 0.30), and province-stratified discrimination was lower in Guangxi (ROC-AUC 0.681) than in Guizhou (0.707); spatial block cross-validation using accessibility-profile clusters was close to the random-split estimate (ROC-AUC 0.692). County identifiers were available only for Guangxi, so county-level validation was restricted to that province; administrative location identifiers performed slightly better than the six distance variables (ROC-AUC 0.702\u20130.711), so the geographic domain does not capture all spatial information. Eighth, geographic accessibility was computed on the April 2026 road network using the 2024 facility registry, whereas symptom onset occurred mostly in 2018\u20132024, and the measures were assigned at village or community centroids; road construction, facility relocation, and within-village heterogeneity are therefore not captured. The geographic domain accounted for 15.6% of domain-level SHAP, but removing it did not materially change discrimination (\u0394ROC-AUC 0.003); its contribution therefore overlaps with other predictors and does not represent independent incremental value. Finally, findings from Guangxi and Guizhou may not generalise to regions with different terrain, facility distribution, insurance arrangements, or care pathways."),
("Delayed entry into TB-designated care was common among pulmonary TB patients",
"Delayed entry into TB-designated care was common among pulmonary TB patients in Guangxi and Guizhou. Geographic accessibility was one of several informative predictor domains, alongside temporal, demographic, and key-population characteristics. It accounted for a substantial share of model explanation, but removing it did not materially change discrimination; adding it to a conventional demographic and clinical model improved discrimination, indicating incremental value relative to conventional predictors. TB patient-delay research should therefore include direct measures of spatial access while avoiding claims that geography alone explains delay. In this setting, the model is a retrospective, surveillance-based planning tool that can help identify areas and pathways where proactive screening, referral support, transport-aware service planning, and seasonal outreach may be most needed. Because discrimination was moderate, decision-curve benefit was limited at low thresholds, and temporal validation showed limited transportability, spatial and external validation and prospective implementation studies are required before routine programme use."),
]

count = 0
for prefix, new in repls:
    found = False
    for p in doc.paragraphs:
        if p.text.strip().startswith(prefix):
            if p.runs:
                p.runs[0].text = new
                for r in p.runs[1:]:
                    r.text = ""
            else:
                p.add_run(new)
            found = True
            count += 1
            break
    if not found:
        print("NOT FOUND:", prefix[:60])

doc.save(path)
print("paragraphs replaced:", count)
